-- ============================================================================
-- 0026_spell_tokens_full_srd.sql
--
-- Bring the spell-token library to the FULL 339 SRD list.
--   1. Reconcile 3 naming mismatches to their SRD names.
--   2. Insert every SRD spell that has no art yet, with a first-letter
--      monogram placeholder (/icons/spells/_mono/<L>.svg) + full stats.
-- Existing art tokens are untouched. Paste into Supabase SQL Editor -> Run.
-- Idempotent.
-- ============================================================================

do $$
declare
  me uuid;
begin
  select id into me from auth.users where email = 'vinces.gerardo@gmail.com';
  if me is null then raise exception 'No auth user for that email.'; end if;

  -- 1. Reconcile naming mismatches (keep their art).
  update public.token_assets set
    name = 'Blindness/Deafness', details = jsonb_set(coalesce(details,'{}'::jsonb),'{spell,name}', '"Blindness/Deafness"'::jsonb)
    where owner_id = me and token_type = 'spell' and name = 'Blindness';
  update public.token_assets set
    name = 'Conjure Minor Elementals', details = jsonb_set(coalesce(details,'{}'::jsonb),'{spell,name}', '"Conjure Minor Elementals"'::jsonb)
    where owner_id = me and token_type = 'spell' and name = 'Conjure Minor Elemental';
  update public.token_assets set
    name = 'Conjure Woodland Beings', details = jsonb_set(coalesce(details,'{}'::jsonb),'{spell,name}', '"Conjure Woodland Beings"'::jsonb)
    where owner_id = me and token_type = 'spell' and name = 'Conjure Woodland Being';

  -- 2. Insert SRD spells that have no art (placeholder tile + stats).
  insert into public.token_assets (owner_id, name, image_url, token_type, size_category, details)
  select me, v.name, v.image_url, 'spell', 'medium',
         jsonb_build_object('kind','spell','spell', v.spell::jsonb)
  from (values
    ('Druidcraft', '/icons/spells/_mono/D.svg', '{"name":"Druidcraft","level":0,"school":"Transmutation","castingTime":"Action","range":"30 feet","components":"V, S","duration":"Instantaneous","classes":["Druid"]}'),
    ('Elementalism', '/icons/spells/_mono/E.svg', '{"name":"Elementalism","level":0,"school":"Transmutation","castingTime":"Action","range":"30 feet (5 ft. Square)","components":"V, S","duration":"Instantaneous","classes":["Druid","Sorcerer","Wizard"]}'),
