    ('Message', '/icons/spells/_mono/M.svg', '{"name":"Message","level":0,"school":"Transmutation","castingTime":"Action","range":"120 feet","components":"S, M (a copper wire)","duration":"1 round","classes":["Bard","Druid","Sorcerer","Wizard"]}'),
